func TestDefaultSectionHeader(t *testing.T) {
	tests := []struct {
		section int
		want    string
	}{
		{1, "User Commands Manual"},
		{2, "System Calls Manual"},
		{3, "Library Functions Manual"},
		{4, "Special Files Manual"},
		{5, "File Formats Manual"},
		{6, "Games Manual"},
		{7, "Miscellaneous Information Manual"},
		{8, "System Administration Commands"},
		{99, "User Commands Manual"}, // fallback
	}

	for _, tt := range tests {
		t.Run(fmt.Sprintf("section_%d", tt.section), func(t *testing.T) {
			got := DefaultSectionHeader(tt.section)
			if got != tt.want {
				t.Errorf("DefaultSectionHeader(%d) = '%s', want '%s'", tt.section, got, tt.want)
			}
		})
	}
}

func TestInferManPageMetadata(t *testing.T) {
	fixedDate := time.Date(2026, 9, 6, 12, 0, 0, 0, time.UTC)

	t.Run("explicit fields override all defaults", func(t *testing.T) {
		mp := spec.ManPageConfig{
			Source:  "docs/craftpack.1.md",
			Section: 1,
			Title:   "my-title",
			Header:  "Custom Header",
			Footer:  "Custom Footer v1",
		}
		cfg := &spec.CraftpackConfig{
			Name:    "craftpack",
			Command: "craftpack",
		}

		meta := InferManPageMetadata(mp, cfg, "v1.0.0", fixedDate)
		if meta.Title != "MY-TITLE" {
			t.Errorf("expected Title 'MY-TITLE', got '%s'", meta.Title)
		}
		if meta.Section != 1 {
			t.Errorf("expected Section 1, got %d", meta.Section)
		}
		if meta.Header != "Custom Header" {
			t.Errorf("expected Header 'Custom Header', got '%s'", meta.Header)
		}
		if meta.Footer != "Custom Footer v1" {
			t.Errorf("expected Footer 'Custom Footer v1', got '%s'", meta.Footer)
		}
		if meta.Date != "2026-09-06" {
			t.Errorf("expected Date '2026-09-06', got '%s'", meta.Date)
		}
	})

	t.Run("inferred defaults from config and section", func(t *testing.T) {
		mp := spec.ManPageConfig{
			Source:  "docs/manual.md",
			Section: 5,
		}
		cfg := &spec.CraftpackConfig{
			Name:    "myapp",
			Command: "mycmd",
		}

		meta := InferManPageMetadata(mp, cfg, "2.3.4", fixedDate)
		if meta.Title != "MYCMD" {
			t.Errorf("expected Title 'MYCMD' (from command), got '%s'", meta.Title)
		}
		if meta.Section != 5 {
			t.Errorf("expected Section 5, got %d", meta.Section)
		}
		if meta.Header != "File Formats Manual" {
			t.Errorf("expected Header 'File Formats Manual', got '%s'", meta.Header)
		}
		if meta.Footer != "myapp 2.3.4" {
			t.Errorf("expected Footer 'myapp 2.3.4', got '%s'", meta.Footer)
		}
		if meta.Date != "2026-09-06" {
			t.Errorf("expected Date '2026-09-06', got '%s'", meta.Date)
		}
	})

	t.Run("title fallback to name when command is empty", func(t *testing.T) {
		mp := spec.ManPageConfig{Section: 1}
		cfg := &spec.CraftpackConfig{Name: "appname"}

		meta := InferManPageMetadata(mp, cfg, "1.0", fixedDate)
		if meta.Title != "APPNAME" {
			t.Errorf("expected Title 'APPNAME', got '%s'", meta.Title)
		}
	})

	t.Run("section 5 title inferred from source filename", func(t *testing.T) {
		mp := spec.ManPageConfig{
			Source:  "docs/manuals/craftpack.yml.5.md",
			Section: 5,
		}
		cfg := &spec.CraftpackConfig{
			Name:    "craftpack",
			Command: "craftpack",
		}

		meta := InferManPageMetadata(mp, cfg, "1.0.0", fixedDate)
		if meta.Title != "CRAFTPACK.YML" {
			t.Errorf("expected Title 'CRAFTPACK.YML', got '%s'", meta.Title)
		}
	})

	t.Run("section 5 title derived from config when source has non-matching filename", func(t *testing.T) {
		mp := spec.ManPageConfig{
			Source:  "docs/config.md",
			Section: 5,
		}
		cfg := &spec.CraftpackConfig{
			Name:    "craftpack",
			Command: "craftpack",
		}

		meta := InferManPageMetadata(mp, cfg, "1.0.0", fixedDate)
		if meta.Title != "CRAFTPACK" {
			t.Errorf("expected Title 'CRAFTPACK', got '%s'", meta.Title)
		}
	})

	t.Run("title inferred from explicit name", func(t *testing.T) {
		mp := spec.ManPageConfig{
			Source:  "docs/manual.md",
			Section: 5,
			Name:    "custom-manifest.yml",
		}
		cfg := &spec.CraftpackConfig{
			Name:    "craftpack",
			Command: "craftpack",
		}

		meta := InferManPageMetadata(mp, cfg, "1.0.0", fixedDate)
		if meta.Title != "CUSTOM-MANIFEST.YML" {
			t.Errorf("expected Title 'CUSTOM-MANIFEST.YML', got '%s'", meta.Title)
		}
	})
}

func TestFormatTitleHeaderDirective(t *testing.T) {
	meta := ManPageMetadata{
		Title:   "CRAFTPACK",
		Section: 1,
		Date:    "2026-09-06",
		Header:  "User Commands Manual",
		Footer:  "craftpack 1.0.0",
	}

	directive := FormatTitleHeaderDirective(meta)
	expected := "% CRAFTPACK(1) craftpack 1.0.0 | User Commands Manual\n\n"
	if directive != expected {
		t.Errorf("expected directive:\n%q\ngot:\n%q", expected, directive)
	}

	// Without footer
	metaNoFooter := ManPageMetadata{Title: "TOOL", Section: 2, Header: "System Calls"}
	directiveNoFooter := FormatTitleHeaderDirective(metaNoFooter)
	expectedNoFooter := "% TOOL(2) | System Calls\n\n"
	if directiveNoFooter != expectedNoFooter {
		t.Errorf("expected directive:\n%q\ngot:\n%q", expectedNoFooter, directiveNoFooter)
	}

	// Without header
	metaNoHeader := ManPageMetadata{Title: "TOOL", Section: 2, Footer: "tool 1.0"}
	directiveNoHeader := FormatTitleHeaderDirective(metaNoHeader)
	expectedNoHeader := "% TOOL(2) tool 1.0\n\n"
	if directiveNoHeader != expectedNoHeader {
		t.Errorf("expected directive:\n%q\ngot:\n%q", expectedNoHeader, directiveNoHeader)
	}
}

func TestFormatTitleHeaderDirective_PipeSanitization(t *testing.T) {
	meta := ManPageMetadata{
		Title:   "TOOL | CLI",
		Section: 1,
		Header:  "User | Manual",
		Footer:  "v1.0 | 2026",
	}

	directive := FormatTitleHeaderDirective(meta)
	expected := "% TOOL - CLI(1) v1.0 - 2026 | User - Manual\n\n"
	if directive != expected {
		t.Errorf("expected directive:\n%q\ngot:\n%q", expected, directive)
	}

	// Verify that title only sanitizes pipe without adding extra delimiters
	metaTitleOnly := ManPageMetadata{
		Title:   "TOOL | CLI",
		Section: 1,
	}
	directiveTitleOnly := FormatTitleHeaderDirective(metaTitleOnly)
	expectedTitleOnly := "% TOOL - CLI(1)\n\n"
	if directiveTitleOnly != expectedTitleOnly {
		t.Errorf("expected directive:\n%q\ngot:\n%q", expectedTitleOnly, directiveTitleOnly)
	}
}

func TestValidateZeroMarkup(t *testing.T) {
	validMarkdown := []byte("# NAME\ncraftpack - tool\n\n# DESCRIPTION\nValid doc\n")
	if err := ValidateZeroMarkup(validMarkdown); err != nil {
		t.Errorf("expected valid markdown to pass, got: %v", err)
	}

	invalidMarkdown := []byte("---\ntitle: Foo\n---\n# NAME\nfoo\n")
	if err := ValidateZeroMarkup(invalidMarkdown); err == nil {
		t.Errorf("expected error for YAML front-matter, got nil")
	} else if !strings.Contains(err.Error(), ErrZeroMarkupViolation.Error()) {
		t.Errorf("expected ErrZeroMarkupViolation, got: %v", err)
	}

	invalidWithWhitespace := []byte("   \n\t---\nsection: 1\n---\n")
	if err := ValidateZeroMarkup(invalidWithWhitespace); err == nil {
		t.Errorf("expected error for YAML front-matter with leading whitespace")
	}
}

func TestRenderRoff(t *testing.T) {
	rawMarkdown := `# NAME
craftpack \- Standardized Linux packaging factory

# SYNOPSIS
**craftpack** build [options]

# DESCRIPTION
Craftpack compiles packages deterministically.

# EXAMPLES
Run build:
` + "```\ncraftpack build --spec craftpack.yml\n```\n"

	meta := ManPageMetadata{
		Title:   "CRAFTPACK",
		Section: 1,
		Date:    "2026-09-06",
		Header:  "User Commands Manual",
		Footer:  "craftpack 1.0.0",
	}

	roffBytes, err := RenderRoff([]byte(rawMarkdown), meta)
	if err != nil {
		t.Fatalf("unexpected error rendering roff: %v", err)
	}

	roff := string(roffBytes)

	// Check roff directives
	if !strings.Contains(roff, ".TH CRAFTPACK(1) craftpack 1.0.0 | User Commands Manual") {
		t.Errorf("missing .TH title header in roff:\n%s", roff)
	}
	if !strings.Contains(roff, ".SH NAME") {
		t.Errorf("missing .SH NAME section header in roff")
	}
	if !strings.Contains(roff, ".SH SYNOPSIS") {
		t.Errorf("missing .SH SYNOPSIS section header in roff")
	}
	if !strings.Contains(roff, ".SH DESCRIPTION") {
		t.Errorf("missing .SH DESCRIPTION section header in roff")
	}
	if !strings.Contains(roff, ".EX") || !strings.Contains(roff, ".EE") {
		t.Errorf("missing code block .EX/.EE in roff:\n%s", roff)
	}
}

func TestCompressRoffAndDecompressRoundtrip(t *testing.T) {
	sampleRoff := []byte(".TH TEST 1\n.SH NAME\ntest - tool\n")
	fixedTime := time.Date(2026, 9, 6, 10, 0, 0, 0, time.UTC)

	compressed, err := CompressRoff(sampleRoff, fixedTime)
	if err != nil {
		t.Fatalf("failed to compress roff: %v", err)
	}

	// Decompress and verify content
	gr, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		t.Fatalf("failed to initialize gzip reader: %v", err)
	}
	defer gr.Close()

	if gr.Header.ModTime.UTC() != fixedTime {
		t.Errorf("expected gzip ModTime %v, got %v", fixedTime, gr.Header.ModTime.UTC())
	}

	decompressed, err := io.ReadAll(gr)
	if err != nil {
		t.Fatalf("failed reading gzip stream: %v", err)
	}

	if !bytes.Equal(decompressed, sampleRoff) {
		t.Errorf("decompressed content does not match original roff")
	}
}

func TestSynthesizeManPage(t *testing.T) {
	tempWorkspace := t.TempDir()

	// Write a valid pristine markdown file
	docRelPath := filepath.Join("docs", "tool.1.md")
	docFullPath := filepath.Join(tempWorkspace, docRelPath)
	if err := os.MkdirAll(filepath.Dir(docFullPath), 0755); err != nil {
		t.Fatalf("failed to create docs dir: %v", err)
	}

	markdownContent := `# NAME
tool - a useful CLI utility

# SYNOPSIS
**tool** [options]
`
	if err := os.WriteFile(docFullPath, []byte(markdownContent), 0644); err != nil {
		t.Fatalf("failed to write test markdown: %v", err)
	}

	mp := spec.ManPageConfig{
		Source:  docRelPath,
		Section: 1,
		Title:   "TOOL",
	}

	cfg := &spec.CraftpackConfig{
		Name:    "mytool",
		Command: "tool",
	}

	fixedTime := time.Date(2026, 9, 6, 12, 0, 0, 0, time.UTC)
	res, err := SynthesizeManPage(mp, cfg, tempWorkspace, "v1.2.3", fixedTime)
	if err != nil {
		t.Fatalf("unexpected error synthesizing man page: %v", err)
	}

	expectedDest := "/usr/share/man/man1/tool.1.gz"
	if res.DestinationPath != expectedDest {
		t.Errorf("expected DestinationPath '%s', got '%s'", expectedDest, res.DestinationPath)
	}
	if res.RelPath() != "usr/share/man/man1/tool.1.gz" {
		t.Errorf("expected RelPath 'usr/share/man/man1/tool.1.gz', got '%s'", res.RelPath())
	}
	if res.Mode != fsutil.FileMode {
		t.Errorf("expected Mode 0644, got %v", res.Mode)
	}
	if res.Section != 1 {
		t.Errorf("expected Section 1, got %d", res.Section)
	}
	if res.Command != "tool" {
		t.Errorf("expected Command 'tool', got '%s'", res.Command)
	}

	// Verify compressed content can be decompressed
	gr, err := gzip.NewReader(bytes.NewReader(res.Content))
	if err != nil {
		t.Fatalf("failed to decompress synthesized content: %v", err)
	}
	decompressed, err := io.ReadAll(gr)
	gr.Close()
	if err != nil {
		t.Fatalf("failed to read decompressed stream: %v", err)
	}

	decompressedStr := string(decompressed)
	if !strings.Contains(decompressedStr, ".TH TOOL(1)") {
		t.Errorf("missing .TH TOOL(1) in decompressed roff:\n%s", decompressedStr)
	}
	if !strings.Contains(decompressedStr, ".SH NAME") {
		t.Errorf("missing .SH NAME in decompressed roff")
	}
}

func TestSynthesizeManPage_Errors(t *testing.T) {
	tempWorkspace := t.TempDir()

	cfg := &spec.CraftpackConfig{Name: "app", Command: "app"}
	now := time.Now()

	// Empty source
	_, err := SynthesizeManPage(spec.ManPageConfig{Source: "", Section: 1}, cfg, tempWorkspace, "1.0", now)
	if err == nil || !strings.Contains(err.Error(), ErrEmptySource.Error()) {
		t.Errorf("expected ErrEmptySource, got: %v", err)
	}

	// Invalid sections (< 1 or > 8)
	_, err = SynthesizeManPage(spec.ManPageConfig{Source: "doc.md", Section: 0}, cfg, tempWorkspace, "1.0", now)
	if err == nil || !strings.Contains(err.Error(), ErrInvalidSection.Error()) {
		t.Errorf("expected ErrInvalidSection for 0, got: %v", err)
	}

	_, err = SynthesizeManPage(spec.ManPageConfig{Source: "doc.md", Section: 9}, cfg, tempWorkspace, "1.0", now)
	if err == nil || !strings.Contains(err.Error(), ErrInvalidSection.Error()) {
		t.Errorf("expected ErrInvalidSection for 9, got: %v", err)
	}

	// Traversal source
	_, err = SynthesizeManPage(spec.ManPageConfig{Source: "../outside.md", Section: 1}, cfg, tempWorkspace, "1.0", now)
	if err == nil || !strings.Contains(err.Error(), "boundary violation") {
		t.Errorf("expected boundary violation error, got: %v", err)
	}

	// Non-existent source
	_, err = SynthesizeManPage(spec.ManPageConfig{Source: "missing.md", Section: 1}, cfg, tempWorkspace, "1.0", now)
	if err == nil {
		t.Errorf("expected error for missing source file, got nil")
	}

	// Zero-Markup violation in source file
	frontmatterFile := filepath.Join(tempWorkspace, "frontmatter.md")
	_ = os.WriteFile(frontmatterFile, []byte("---\ntitle: Bad\n---\n# NAME\n"), 0644)
	_, err = SynthesizeManPage(spec.ManPageConfig{Source: "frontmatter.md", Section: 1}, cfg, tempWorkspace, "1.0", now)
	if err == nil || !strings.Contains(err.Error(), ErrZeroMarkupViolation.Error()) {
		t.Errorf("expected ErrZeroMarkupViolation, got: %v", err)
	}
}

